/* ---------- CRM: cola de envíos ---------- */
function v15Encolar(entity_type, entity_id, action) {
  const c = V15.crm; if (c.status !== 'active') return null;
  const ev = { id: 'SYN-' + String(V15.sigSync++).padStart(4, '0'), entity_type, entity_id, action: action || 'create', status: c.entities[entity_type] ? 'pending' : 'skipped', attempts: 0, next_attempt_at: '', external_id: '', response_code: '', last_error: '', idempotency_key: wxIdem(), f: wxAhora() };
  if (V15.cola.some((x) => x.entity_type === entity_type && x.entity_id === entity_id && x.action === ev.action && x.status === 'pending')) return null;
  V15.cola.unshift(ev); return ev;
}
const _wxLead15 = wxLead;
wxLead = function (source, d, act) { const l = _wxLead15(source, d, act); v15Encolar('marketing_lead', l.id, 'create'); return l; };

/* ---------- Resumen ---------- */
function v15Barras(dias) {
  const W = 640, H = 170, max = Math.max(...dias.map((x) => x.visitas)) * 1.1, bw = W / dias.length;
  return '<svg class="s15chart" viewBox="0 0 ' + W + ' ' + (H + 22) + '" role="img" aria-label="Visitas diarias de los últimos 30 días, de ' + Math.min(...dias.map((x) => x.visitas)) + ' a ' + Math.max(...dias.map((x) => x.visitas)) + '">' +
    [0.5, 1].map((p) => '<line x1="0" x2="' + W + '" y1="' + (H - H * p / 1.1) + '" y2="' + (H - H * p / 1.1) + '" class="s15grid"/>').join('') +
    dias.map((x, i) => { const h = x.visitas / max * H; return '<rect x="' + (i * bw + 2) + '" y="' + (H - h) + '" width="' + (bw - 4) + '" height="' + h + '" rx="3" class="s15bar' + (i === dias.length - 1 ? ' hoy' : '') + '"><title>' + fmtF(x.d) + ': ' + x.visitas + ' visitas</title></rect>'; }).join('') +
    [0, 14, 29].map((i) => '<text x="' + (i * bw + bw / 2) + '" y="' + (H + 16) + '" text-anchor="' + (i === 0 ? 'start' : i === 29 ? 'end' : 'middle') + '" class="s15ax">' + fmtF(dias[i].d).slice(0, 5) + '</text>').join('') + '</svg>';
}
