/* ---------- Webinars ---------- */
const INS_EST = { registered: 'Inscrito', attended: 'Asistió', no_show: 'No asistió', cancelled: 'Cancelado' };
function wpWebinars(root) {
  const w = V15.webinars.find((x) => x.slug === V15P.wbSel) || V15.webinars[0]; const WE = { draft: 'Borrador', published: 'Publicado', live: 'En vivo', finished: 'Terminado', cancelled: 'Cancelado' };
  root.insertAdjacentHTML('beforeend', '<div class="s15g"><div class="stack">' + card15('Webinars', 'video', tabla([{ l: 'Webinar', f: (x) => '<b>' + esc(x.title) + '</b><br><span class="tiny muted">' + esc(v15Cuando(x.starts_at)) + ' · ' + esc(WB_PROV[x.meeting_provider]) + '</span>' }, { l: 'Inscritos', f: (x) => '<span class="num">' + x.ins.filter((i) => i.status !== 'cancelled').length + ' / ' + x.capacity + '</span>' }, { l: 'Estado', f: (x) => chip(WE[x.status]) }, { l: 'Grabación', f: (x) => x.recording_public ? chip('Publicada', 'ok') : '<span class="muted small">No publicada</span>' }], V15.webinars, { click: true }), verSitio('web-webinars', 'Ver en el sitio')) +
    card15('Inscritos · ' + w.title, 'people', tabla([{ l: 'Persona', f: (i) => '<b>' + esc(i.nombre) + '</b><br><span class="tiny muted">' + esc(i.email) + '</span>' }, { l: 'Empresa', k: 'empresa' }, { l: 'Lead', f: (i) => '<code class="tiny">' + esc(i.lead) + '</code>' }, { l: 'Inscrito', k: 'registered_at' }, { l: 'Asistencia', f: (i) => '<select class="input" data-wbs="' + esc(i.token) + '" aria-label="Asistencia de ' + esc(i.nombre) + '">' + Object.entries(INS_EST).map(([k, l]) => '<option value="' + k + '"' + (i.status === k ? ' selected' : '') + '>' + l + '</option>').join('') + '</select>' }], w.ins, { vacioT: 'Aún no hay inscritos', vacioS: 'Las inscripciones del sitio aparecen aquí.' }), '<span class="tiny muted">Recordatorios 24 h y 1 h antes</span>') + '</div>' +
    '<div class="stack">' + card15('Grabación', 'play', '<p class="small">Solo se publica si el ponente y los asistentes fueron <b>informados</b> de la grabación.</p><label class="s15ck" for="wb-inf"><input type="checkbox" id="wb-inf"' + (w.informados ? ' checked' : '') + '><span>El ponente y los asistentes fueron informados de la grabación.</span></label>' + sw('wb-pub', w.recording_public, 'Publicar la grabación en el sitio', '') + '<button class="btn pri" id="wb-save" style="margin-top:10px">Guardar</button><p class="tiny muted">Publicar requiere ' + permiso('web.webinars.publish') + '.</p>') +
    card15('Nuevo webinar', 'plus', '<div class="stack" style="gap:10px">' + wpCampo('wn-t', 'Título', '') + '<div class="grid g2">' + campo('wn-f', 'Fecha', 'date', '2026-12-03') + campo('wn-h', 'Hora', 'time', '18:00') + '</div>' + wpCampo('wn-c', 'Cupos', 100, { tipo: 'number' }) + wpCampo('wn-p', 'Ponente', '') + '<button class="btn" id="wn-add">Crear y publicar</button></div>') + '</div></div>');
  bindTabla(root, V15.webinars, (x) => { V15P.wbSel = x.slug; render(); });
  $$('[data-wbs]', root).forEach((s) => s.addEventListener('change', () => { w.ins.find((i) => i.token === s.dataset.wbs).status = s.value; toast('Asistencia actualizada'); }));
  $('#wb-save', root).onclick = () => { const inf = $('#wb-inf', root).checked; const pub = $('#wb-pub', root).checked; if (pub && !inf) { toast('Primero confirma que el ponente y los asistentes fueron informados', 'warn'); return; } w.informados = inf; w.recording_public = pub; toast('Grabación ' + (pub ? 'publicada' : 'no publicada')); render(); };
  $('#wn-add', root).onclick = () => { const t = $('#wn-t', root).value.trim(); if (!t) { toast('Escribe el título', 'warn'); return; } const [y, m, d] = $('#wn-f', root).value.split('-').map(Number); const [hh, mm] = $('#wn-h', root).value.split(':').map(Number); V15.webinars.unshift({ slug: norm15(t).replace(/[^a-z0-9]+/g, '-').slice(0, 40), title: t, description: 'Por completar.', speaker_name: $('#wn-p', root).value.trim() || 'Por definir', speaker_title: '', starts_at: new Date(y, m - 1, d, hh, mm), duration_minutes: 60, meeting_provider: 'meet', meeting_url: '', capacity: Math.max(1, +$('#wn-c', root).value || 100), status: 'published', recording_public: false, informados: false, ins: [] }); toast('Webinar publicado'); render(); };
}

/* ---------- Reseñas de Google ---------- */
function wpResenas(root) {
  const R0 = V15.resenas;
  root.insertAdjacentHTML('beforeend', nota('Se muestran <b>reseñas reales</b> del perfil de Google Business mediante la API oficial, con atribución y sin editar el texto. Solo se filtra por calificación mínima y cantidad: <b>no se eligen reseñas a mano</b>. En el prototipo las reseñas son de ejemplo.', 'warn') +
    '<div class="s15g" style="margin-top:12px"><div class="stack">' + card15('Reseñas obtenidas (caché)', 'starf', tabla([{ l: 'Autor', f: (s) => '<b>' + esc(s.autor) + '</b> <span class="w-ejt">Ejemplo</span>' }, { l: 'Calificación', f: (s) => '<span class="num">' + '★'.repeat(s.rating) + '☆'.repeat(5 - s.rating) + '</span>' }, { l: 'Texto', f: (s) => '<span class="small">' + esc(s.body) + '</span>' }, { l: 'Fecha', k: 'f' }, { l: 'En el sitio', f: (s) => s.rating >= R0.min_rating && R0.snaps.filter((x) => x.rating >= R0.min_rating).indexOf(s) < R0.max_to_show ? chip('Se muestra', 'ok') : chip('Filtrada', 'na') }], R0.snaps), verSitio('web/resenas', 'Ver en la portada')) + '</div>' +
    '<div class="stack">' + card15('Conexión con Google', 'globe', '<div class="stack" style="gap:10px">' + wpCampo('rv-pl', 'Place ID del perfil', R0.place_id, { ph: 'ChIJ…' }) + wpCampo('rv-s', 'Llave de la API (referencia a secreto)', R0.api_secret_ref, { ph: 'secret://google/places' }) + '<div class="grid g2"><label class="field" for="rv-min"><span>Calificación mínima</span><select id="rv-min">' + [1, 2, 3, 4, 5].map((n) => '<option' + (R0.min_rating === n ? ' selected' : '') + '>' + n + '</option>').join('') + '</select></label>' + wpCampo('rv-max', 'Cantidad a mostrar', R0.max_to_show, { tipo: 'number' }) + '</div>' + wpCampo('rv-ttl', 'Caché (horas)', R0.cache_ttl_hours, { tipo: 'number', hint: 'Según los términos del proveedor · <code>web.review_cache_max_hours</code> a confirmar' }) +
      '<div class="row"><button class="btn pri" id="rv-save">Guardar</button><button class="btn" id="rv-sync">' + ic('sync', 16) + 'Actualizar ahora</button></div><p class="tiny muted">Última lectura: ' + esc(R0.last_fetched_at || 'nunca') + ' · Gestionar requiere ' + permiso('web.review_sources.manage') + '.</p></div>', sbadge(R0.status === 'active' ? 'Activa' : 'Sin conectar', R0.status === 'active' ? 'ok' : 'na')) + '</div></div>');
  $('#rv-save', root).onclick = () => { R0.place_id = $('#rv-pl', root).value.trim(); R0.api_secret_ref = $('#rv-s', root).value.trim(); R0.min_rating = +$('#rv-min', root).value; R0.max_to_show = Math.max(1, Math.min(6, +$('#rv-max', root).value || 3)); R0.cache_ttl_hours = Math.max(1, +$('#rv-ttl', root).value || 24); toast('Filtro guardado: la portada ya lo aplica'); render(); };
  $('#rv-sync', root).onclick = () => { if (!R0.place_id || !/^secret:\/\//.test(R0.api_secret_ref)) { toast('Completa el Place ID y la referencia a secreto', 'warn'); return; } R0.status = 'active'; R0.last_fetched_at = wxAhora(); toast('Reseñas actualizadas (simulado)'); render(); };
}

/* ---------- Calculadora de ahorro ---------- */
function wpAhorro(root) {
  const A = V15.ahorro; const S = A.sup;
  root.insertAdjacentHTML('beforeend', '<div class="s15g"><div class="stack">' + card15('Cálculos recibidos', 'piggy', tabla([{ l: 'Fecha', k: 'f' }, { l: 'Lead', f: (c) => '<code class="tiny">' + esc(c.lead) + '</code>' }, { l: 'Datos', f: (c) => '<span class="small">' + esc(c.inputs.trabajadores) + ' trab. · ' + esc(c.inputs.sedes) + ' sedes · ' + esc(c.inputs.registros) + ' reg./mes</span>' }, { l: 'Resultado', f: (c) => '<b class="num">' + c.horas + ' h/mes</b>' + (c.costo != null ? '<br><span class="tiny">' + wxSoles(c.costo) + '</span>' : '') }, { l: 'Idempotencia', f: (c) => '<code class="tiny">' + esc(c.idem) + '</code>' }], A.calculos, { vacioT: 'Aún no hay cálculos con datos', vacioS: 'Cuando alguien pida el detalle por correo, aparecerá aquí.' }), verSitio('web-calculadora-ahorro', 'Ver la calculadora')) + '</div>' +
    '<div class="stack">' + card15('Supuestos (visibles en el sitio)', 'grid', '<div class="stack" style="gap:10px">' + wpCampo('as-r', 'Horas por registro o formato', S.horasRegistro, { tipo: 'number' }) + wpCampo('as-s', 'Horas al mes por sede en reportes', S.horasReportePorSede, { tipo: 'number' }) + wpCampo('as-p', 'Reducción estimada (%)', S.reduccion, { tipo: 'number' }) + wpCampo('as-c', 'Costo por hora referencial (S/)', S.costoHora, { tipo: 'number', ph: 'Vacío: no se asume' }) + wpCampo('as-d', 'Aviso', A.disclaimer, { area: true }) + sw('as-v', A.to_validate, 'Supuestos por validar', 'Se indica en el resultado.') + '<button class="btn pri" id="as-save">Guardar supuestos</button></div>') + '</div></div>');
  $('#as-save', root).onclick = () => { const n = (id) => $('#' + id, root).value; if (!(+n('as-r') >= 0 && +n('as-s') >= 0 && +n('as-p') > 0 && +n('as-p') <= 90)) { toast('Revisa los valores (reducción entre 1 y 90 %)', 'warn'); return; } Object.assign(S, { horasRegistro: +n('as-r'), horasReportePorSede: +n('as-s'), reduccion: +n('as-p'), costoHora: n('as-c') }); A.disclaimer = $('#as-d', root).value.trim() || A.disclaimer; A.to_validate = $('#as-v', root).checked; toast('Supuestos guardados: la calculadora ya los usa'); render(); };
}

